let _gridContainer = null;

export async function initAllVideosGrid() {
  const section  = document.getElementById('sectionAllVideos');
  const container = document.getElementById('allVideosGrid');
  if (!container) return;
  if (_gridContainer) return;

  try {
    _gridContainer = container;

    if (!document.getElementById('allVideosSearch') && section) {
      const searchWrap = document.createElement('div');
      searchWrap.style.cssText = 'display: flex; gap: 12px; margin-bottom: 24px; align-items: center;';
      const searchBar = document.createElement('input');
      searchBar.id = 'allVideosSearch';
      searchBar.type  = 'search';
      searchBar.placeholder = 'Search 700+ videos…';
      searchBar.style.cssText = 'flex: 1; padding: 12px 20px; border-radius: 50px; background: var(--panel-2); border: 1px solid var(--border); color: var(--text); font-family: var(--font-body); font-size: 0.95rem; outline: none; transition: border 0.2s;';
      searchBar.addEventListener('focus', () => searchBar.style.borderColor = 'var(--accent)');
      searchBar.addEventListener('blur',  () => searchBar.style.borderColor = 'var(--border)');
      searchBar.addEventListener('input', () => _applySearch(searchBar.value.trim().toLowerCase()));
      searchWrap.appendChild(searchBar);
      section.insertBefore(searchWrap, container);
    }

    container.innerHTML = '';
    
    // Flatten videos logically by chapter
    const orderedVideos = [];
    CHAPTERS.forEach(ch => {
      const chVideos = RAW_DATA
        .filter(v => v[2] === ch.key)
        .sort((a, b) => a[3] - b[3]);
      if (chVideos.length === 0) return;
      orderedVideos.push({ chapter: ch, videos: chVideos });
    });

    let currentChapterIndex = 0;
    let currentVideoIndex = 0;
    let activeChapterBlock = null;
    let activeChGrid = null;
    const CHUNK_SIZE = 45;

    let observer = null;
    let isRendering = false;

    function renderNextChunk() {
      if (isRendering) return;
      isRendering = true;
      const fragment = document.createDocumentFragment();
      let renderedCount = 0;

      while (renderedCount < CHUNK_SIZE && currentChapterIndex < orderedVideos.length) {
        const chGroup = orderedVideos[currentChapterIndex];
        
        if (!activeChapterBlock) {
          activeChapterBlock = document.createElement('div');
          activeChapterBlock.className = 'av-chapter-block';
          activeChapterBlock.style.cssText = 'grid-column: 1 / -1;';
          
          const header = document.createElement('h3');
          header.style.cssText = 'margin: 36px 0 16px; font-family: var(--font-display); font-size: 1.1rem; font-weight: 700; color: var(--accent); border-bottom: 1px solid var(--border); padding-bottom: 10px;';
          header.textContent = `${chGroup.chapter.name} (${chGroup.videos.length})`;
          activeChapterBlock.appendChild(header);

          activeChGrid = document.createElement('div');
          activeChGrid.style.cssText = 'display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px; margin-bottom: 8px;';
          activeChapterBlock.appendChild(activeChGrid);
          
          fragment.appendChild(activeChapterBlock);
        }

        const v = chGroup.videos[currentVideoIndex];
        if (!v || v.length < 3) {
          activeChGrid.innerHTML += `<div style="color:red">Bad Video Data: ${JSON.stringify(v)}</div>`;
        } else {
          try {
            activeChGrid.appendChild(_makeCard(v));
          } catch(e) {
            activeChGrid.innerHTML += `<div style="color:red">Card Error: ${e.message}</div>`;
          }
        }
        currentVideoIndex++;
        renderedCount++;

        if (currentVideoIndex >= chGroup.videos.length) {
          currentChapterIndex++;
          currentVideoIndex = 0;
          activeChapterBlock = null; // Start a new block next time
        }
      }

      if (fragment.children.length > 0 || renderedCount > 0) {
        container.appendChild(fragment);
      }

      if (currentChapterIndex >= orderedVideos.length) {
        // Done rendering all videos
        if (observer) observer.disconnect();
      }
      
      // Delay next render to allow DOM to layout
      setTimeout(() => { isRendering = false; }, 100);
    }

    // Render playlist section FIRST (at the top) before initial chunk
    _renderPlaylistSection(null);

    // Initial chunk
    renderNextChunk();

    // Intersection Observer for infinite scrolling
    const sentinel = document.createElement('div');
    sentinel.style.cssText = 'grid-column: 1 / -1; height: 100px; background: transparent;';
    container.appendChild(sentinel);

    observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting && !isRendering) {
        container.removeChild(sentinel);
        renderNextChunk();
        if (currentChapterIndex < orderedVideos.length) {
          container.appendChild(sentinel);
        }
      }
    }, { rootMargin: '400px' });

    window._forceRenderAll = () => {
      if (observer) observer.disconnect();
      if (sentinel && sentinel.parentNode) container.removeChild(sentinel);
      while (currentChapterIndex < orderedVideos.length) {
        isRendering = false;
        renderNextChunk();
      }
      window._forceRenderAll = null;
    };

    observer.observe(sentinel);
  } catch (err) {
    container.innerHTML = `<div style="color:red; padding: 20px;"><h3>Critical Script Failure</h3><pre>${err.stack || err.message}</pre></div>`;
  }
}

window._forceRenderAll = null; function _applySearch(q) {
  if (q && window._forceRenderAll) window._forceRenderAll();
  
  const addToPlaylistBtns = document.querySelectorAll('#allVideosGrid .av-add-btn');

  document.querySelectorAll('#allVideosGrid .av-chapter-block').forEach(block => {
    let anyVisible = false;
    block.querySelectorAll('.av-card').forEach(card => {
      const match = !q || card.dataset.title.includes(q);
      card.style.display = match ? '' : 'none';
      if (match) anyVisible = true;
    });
    block.style.display = anyVisible ? '' : 'none';
  });
}

// ── Custom Playlist (localStorage) ───────────────────────────────────────
const PLAYLIST_KEY = 'fa_custom_playlist';

function _getPlaylist() {
  try { return JSON.parse(localStorage.getItem(PLAYLIST_KEY)) || []; } catch { return []; }
}
function _savePlaylist(list) {
  localStorage.setItem(PLAYLIST_KEY, JSON.stringify(list));
}
function _addToPlaylist(videoId, title) {
  const list = _getPlaylist();
  if (list.find(v => v.id === videoId)) return; // already saved
  list.push({ id: videoId, title });
  _savePlaylist(list);
  _refreshPlaylistSection();
  alert(`Added to your playlist: "${title.slice(0, 50)}…"`);
}
function _renderPlaylistSection(fragment) {
  const existingSection = document.getElementById('customPlaylistSection');
  if (existingSection) existingSection.remove();

  const list = _getPlaylist();
  const section = document.createElement('div');
  section.id = 'customPlaylistSection';
  section.style.cssText = 'grid-column: 1 / -1; margin-top: 40px;';

  const header = document.createElement('h3');
  header.style.cssText = 'margin: 0 0 16px; font-family: var(--font-display); font-size: 1.1rem; font-weight: 700; color: var(--pyq); border-bottom: 1px solid var(--border); padding-bottom: 10px;';
  header.textContent = `⭐ My Playlist (${list.length})`;
  section.appendChild(header);

  if (list.length === 0) {
    const empty = document.createElement('p');
    empty.style.cssText = 'color: var(--muted); font-size: 0.9rem;';
    empty.textContent = 'Use the ⭐ button on any video to save it here. Stored locally in your browser.';
    section.appendChild(empty);
  } else {
    const chGrid = document.createElement('div');
    chGrid.style.cssText = 'display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px;';
    list.forEach(v => {
      const card = _makeCard([v.id, v.title, '', 0], true);
      chGrid.appendChild(card);
    });
    section.appendChild(chGrid);
  }

    if (fragment) {
      fragment.appendChild(section);
    } else {
      _gridContainer.prepend(section);
    }
  }

function _refreshPlaylistSection() {
  const existing = document.getElementById('customPlaylistSection');
  if (existing) existing.remove();
  _renderPlaylistSection(null);
}

export function appendNewVideos(newVideos) {
  if (!_gridContainer || !newVideos || newVideos.length === 0) return;
  newVideos.forEach(v => {
    const chKey = v[2];
    const ch = CHAPTERS.find(c => c.key === chKey);
    if (!ch) return;
    _gridContainer.querySelectorAll('.av-chapter-block').forEach(block => {
      const h3 = block.querySelector('h3');
      if (h3 && h3.textContent.startsWith(ch.name)) {
        const chGrid = block.querySelector('div');
        if (chGrid) chGrid.appendChild(_makeCard(v));
      }
    });
  });
}

function _makeCard(v, isPlaylistCard = false) {
  const [videoId, title] = v;
  const card = document.createElement('div');
  card.className = 'av-card';
  card.dataset.title = (title || '').toLowerCase();

  const esc = (s) => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

  card.innerHTML = `
    <div class="av-thumb" data-id="${videoId}">
      <img class="av-thumb-img" src="https://i.ytimg.com/vi/${videoId}/mqdefault.jpg" loading="lazy" alt="">
      <div class="av-play-overlay">
        <span class="av-play-btn">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
        </span>
      </div>
    </div>
    <div class="av-body">
      <div class="av-title">${esc(title)}</div>
      <div class="av-actions">
        <a class="av-btn av-btn-open" href="https://www.youtube.com/watch?v=${videoId}" target="_blank" rel="noopener noreferrer">↗ Open</a>
        ${isPlaylistCard
          ? `<button class="av-btn av-btn-remove av-rm-btn" data-id="${videoId}">✕ Remove</button>`
          : `<button class="av-btn av-btn-save av-add-btn" data-id="${videoId}" data-title="${esc(title)}">⭐ Save</button>`
        }
      </div>
    </div>
  `;

  // Inline player (Pillar 2)
  const thumb = card.querySelector('.av-thumb');
  thumb.addEventListener('click', () => openInlinePlayer(videoId, title));

  // Save to playlist
  const addBtn = card.querySelector('.av-add-btn');
  if (addBtn) addBtn.addEventListener('click', () => _addToPlaylist(addBtn.dataset.id, addBtn.dataset.title));

  // Remove from playlist
  const rmBtn = card.querySelector('.av-rm-btn');
  if (rmBtn) rmBtn.addEventListener('click', () => {
    const list = _getPlaylist().filter(v => v.id !== rmBtn.dataset.id);
    _savePlaylist(list);
    _refreshPlaylistSection();
  });

  return card;
}



// ── Inline Video Player (Pillar 2) ───────────────────────────────────────
window.openInlinePlayer = function(videoId, title) {
  let modal = document.getElementById('inlinePlayerModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'inlinePlayerModal';
    modal.className = 'ip-modal';

    modal.innerHTML = `
      <div class="ip-modal-inner">
        <div class="ip-modal-header">
          <h3 id="inlinePlayerTitle" class="ip-modal-title"></h3>
          <button id="closeInlinePlayerBtn" class="ip-modal-close" title="Close (Esc)">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
          </button>
        </div>
        <!-- 16:9 Aspect Ratio Container -->
        <div class="ip-player-frame">
          <iframe id="inlinePlayerIframe" allow="autoplay; encrypted-media" allowfullscreen></iframe>
        </div>
      </div>
    `;

    document.body.appendChild(modal);

    const closePlayer = () => {
      modal.classList.remove('open');
      setTimeout(() => {
        modal.style.display = 'none';
        modal.querySelector('#inlinePlayerIframe').src = ''; // Stop video
      }, 200);
    };

    modal.querySelector('#closeInlinePlayerBtn').addEventListener('click', closePlayer);

    // Close on background click
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closePlayer();
    });

    // Close on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.classList.contains('open')) closePlayer();
    });
  }

  modal.querySelector('#inlinePlayerTitle').textContent = title || 'Video';
  modal.querySelector('#inlinePlayerIframe').src = `https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0`;
  modal.style.display = 'flex';
  // Force reflow so the open transition plays every time
  void modal.offsetWidth;
  modal.classList.add('open');
};

